  "manifests/agents/pi-agent.yaml": "# Module 0 lab: the pi agent as an ordinary Kubernetes workload. It gets the\n# LiteLLM key as an environment variable, installs pi from npm at start, and\n# points it at LiteLLM in the cluster.\napiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: pi-agent\n  namespace: agents\nspec:\n  replicas: 1\n  selector:\n    matchLabels: { app: pi-agent }\n  template:\n    metadata:\n      labels: { app: pi-agent }\n    spec:\n      containers:\n        - name: agent\n          image: node:22\n          env:\n            - name: PI_OFFLINE\n              value: \"1\"\n            - name: LITELLM_API_KEY\n              valueFrom:\n                secretKeyRef: { name: litellm-key, key: LITELLM_API_KEY }\n          command: [\"bash\", \"-c\"]\n          args:\n            - |\n              npm install -g --no-audit --no-fund @earendil-works/pi-coding-agent@1.5.2\n              mkdir -p ~/.pi/agent\n              cat > ~/.pi/agent/models.json <<'JSON'\n              {\n                \"providers\": {\n                  \"lab\": {\n                    \"baseUrl\": \"http://litellm.litellm.svc.cluster.local:4000/v1\",\n                    \"api\": \"openai-completions\",\n                    \"apiKey\": \"$LITELLM_API_KEY\",\n                    \"compat\": { \"supportsDeveloperRole\": false, \"supportsReasoningEffort\": false },\n                    \"models\": [{ \"id\": \"default\" }]\n                  }\n                }\n              }\n              JSON\n              touch /tmp/ready\n              sleep infinity\n          readinessProbe:\n            exec: { command: [\"test\", \"-f\", \"/tmp/ready\"] }\n            periodSeconds: 3\n          resources:\n            requests: { memory: 512Mi }\n            limits: { memory: 2Gi }",
  "manifests/policies/pi-agent.yaml": "# The pi lab's sandbox policy: the lab baseline plus one grant, the public npm\n# registry, read-only and for node only, so pi can be installed inside the\n# sandbox. Model access comes from the `litellm` provider (_provider_litellm).\nversion: 1\nfilesystem_policy:\n  include_workdir: true\n  read_only: [/usr, /lib, /proc, /dev/urandom, /app, /etc, /var/log]\n  read_write: [/sandbox, /tmp, /dev/null]\nlandlock:\n  compatibility: best_effort\nprocess:\n  run_as_user: sandbox\n  run_as_group: sandbox\nnetwork_policies:\n  npm_registry:\n    name: npm_registry\n    endpoints:\n      - host: registry.npmjs.org\n        port: 443\n        protocol: rest\n        enforcement: enforce\n        access: read-only\n        # scoped packages are fetched as /@scope%2Fname\n        allow_encoded_slash: true\n    binaries:\n      - path: /usr/bin/node",
  "manifests/openclaw/policies/skills-locked.policy.yaml": "# The \"locked\" production posture for a skills sandbox: its ONLY install egress is the\n# in-cluster Verdaccio registry (registry.openshell.svc.cluster.local:4873). ClawHub and\n# direct public npm are denied at the seal — the registry is the single, auditable source.\n#\n#   openshell policy set agent-0 --policy manifests/openclaw/policies/skills-locked.policy.yaml --wait\n#\n# The lab baseline policy (manifests/policies/baseline.yaml) has no registry rule at all,\n# so skill installs/publishes are denied until you apply this. OpenClaw runs on its own\n# Node 24 (/usr/local/lib/openclaw/node/bin/node), so that binary is listed too.\nversion: 1\nfilesystem_policy:\n  include_workdir: true\n  read_only: [/usr, /lib, /proc, /dev/urandom, /app, /etc, /var/log]\n  read_write: [/sandbox, /tmp, /dev/null]\nlandlock: { compatibility: best_effort }\nprocess: { run_as_user: sandbox, run_as_group: sandbox }\nnetwork_policies:\n  in-cluster-registry:\n    name: in-cluster-registry\n    # access: full + protocol: rest + allow_encoded_slash lets npm fetch SCOPED names\n    # (@workshop/x → /@workshop%2Fx) — the %2F that strict path parsing rejects by default\n    # (a path-traversal / request-smuggling guard). allow_encoded_slash is NOT settable via\n    # `openshell policy update --add-endpoint`; it only lives in policy YAML like this.\n    # Verdaccio uplinks npmjs server-side and caches transitive deps, so @workshop installs\n    # never need the agent to reach public npm directly.\n    endpoints:\n      - { host: registry.openshell.svc.cluster.local, port: 4873, access: full, protocol: rest, enforcement: enforce, allow_encoded_slash: true }\n    binaries: [ { path: /usr/bin/npm }, { path: /usr/local/bin/npm }, { path: /usr/bin/node }, { path: /usr/local/bin/node }, { path: /usr/local/lib/openclaw/node/bin/node } ]"
